<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
const props=defineProps<{refreshKey?:number}>();
const emit=defineEmits(['create','edit','navigate']);
const patterns=ref<any[]>([]),loading=ref(false),error=ref(''),query=ref(''),filter=ref('全部'),sort=ref('newest'),selected=ref<any>(null);
let request=0;
async function load(){const id=++request;loading.value=true;error.value='';try{const r=await fetch('/api/community/patterns');if(!r.ok)throw Error('暂时无法读取创作库，请重试');const data=await r.json();if(id===request)patterns.value=Array.isArray(data)?data:(data.patterns||[])}catch(e:any){if(id===request)error.value=e.message}finally{if(id===request)loading.value=false}}
function image(p:any){const value=p.images?.[0]?.url||p.images?.[0]?.svg||p.svg||'';return value.trim().startsWith('<svg')?'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(value):value}
function method(p:any){return p.creation_method==='remix'||p.source_design_id||p.source_pattern_id?'延续创作':'自由原创'}
const visible=computed(()=>patterns.value.filter(p=>(filter.value==='全部'||method(p)===filter.value)&&(!query.value.trim()||(p.name+' '+p.description).toLowerCase().includes(query.value.trim().toLowerCase()))).sort((a,b)=>sort.value==='newest'?String(b.created_at).localeCompare(String(a.created_at)):String(a.created_at).localeCompare(String(b.created_at))));
function date(value:string){const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})}
function refText(value:any){if(typeof value==='string')return value;return [value.pattern_id||value.pattern,value.gene_code||value.code,value.name||value.document].filter(Boolean).join(' · ')}
function select(p:any){selected.value=selected.value?.id===p.id?null:p;requestAnimationFrame(()=>document.getElementById('community-detail')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'}))}
onMounted(load);watch(()=>props.refreshKey,load);
</script>

<template>
<main class="community-archive">
 <header class="community-heading"><div><p>当代创作库 / COMMUNITY PATTERNS</p><h1>让新的纹样，<em>有处生长。</em></h1><span>在这里收存自由笔画与延续创作。每份作品都可重新编辑，也能继续进入器物设计。</span></div><button class="community-start" @click="emit('navigate','original')">从空白画布开始 ＋</button></header>
 <div class="community-intro-strip"><div><strong>{{patterns.length}}</strong><span>份已入库创作</span></div><p>当代创作保留作者说明与底稿来源，<br>不自动沿用传统纹样的全部寓意。</p><button @click="emit('navigate','library')">查阅传统档案 ↗</button></div>
 <div class="community-toolbar"><div class="community-filters"><button v-for="f in ['全部','自由原创','延续创作']" :class="{active:filter===f}" @click="filter=f">{{f}}</button></div><input v-model="query" type="search" placeholder="搜索作品名称或创作说明" aria-label="搜索当代创作"><select v-model="sort" aria-label="当代创作排序"><option value="newest">最近入库</option><option value="oldest">最早入库</option></select><button class="community-refresh" :disabled="loading" @click="load">{{loading?'读取中…':'刷新'}}</button></div>
 <p v-if="error" class="community-error" role="alert">{{error}} <button @click="load">重新读取</button></p>
 <div v-if="loading&&!patterns.length" class="community-empty" role="status"><span class="empty-mark">纹</span><h2>正在翻开创作库…</h2></div>
 <section v-else-if="!patterns.length&&!error" class="community-empty"><span class="empty-mark">＋</span><h2>第一笔，可以从你开始。</h2><p>画一片花瓣，或让一条线旋转成纹。<br>入库后，就能把它放在茶杯、花器和随身小物上。</p><button class="community-start" @click="emit('navigate','original')">画出我的第一枚纹样 →</button></section>
 <template v-else><p class="community-results">{{query||filter!=='全部'?'当前找到':'共'}} {{visible.length}} 份创作</p><div class="community-grid"><article v-for="p in visible" :key="p.id" class="community-card" :class="{selected:selected?.id===p.id}"><button class="community-art" @click="select(p)" :aria-label="'查看 '+p.name"><img v-if="image(p)" :src="image(p)" :alt="p.name" loading="lazy"><span>{{method(p)}}</span><i>细看 ↗</i></button><div class="community-card-copy"><div class="community-card-meta"><span>当代创作</span><time>{{date(p.created_at)}}</time></div><h2>{{p.name}}</h2><p>{{p.description||'让图形本身，讲述这一笔的想法。'}}</p><div class="community-card-actions"><button @click="emit('create',p.id)">用于器物设计 ↗</button><button @click="emit('edit',p)">继续编辑</button></div></div></article></div><div v-if="!visible.length" class="community-no-match"><p>没有找到匹配作品，试试其他关键词。</p><button @click="query='';filter='全部'">清除筛选</button></div></template>
 <section v-if="selected" id="community-detail" class="community-detail"><div class="community-detail-art"><img :src="image(selected)" :alt="selected.name"></div><div class="community-detail-copy"><button class="community-detail-close" @click="selected=null" aria-label="收起作品详情">收起 ×</button><p class="community-detail-kicker">当代创作 / {{method(selected)}}</p><h2>{{selected.name}}</h2><p>{{selected.description||'这份作品尚未填写创作说明。'}}</p><dl><div><dt>作品编号</dt><dd>{{selected.id}}</dd></div><div><dt>入库日期</dt><dd>{{date(selected.created_at)}}</dd></div><div v-if="selected.source_design_id"><dt>器物底稿</dt><dd><button @click="emit('navigate',selected.source_design_id)">{{selected.source_design_id}} ↗</button></dd></div><div v-if="selected.source_pattern_id"><dt>延续原作</dt><dd>{{selected.source_pattern_id}}</dd></div></dl><div v-if="selected.source_refs?.length" class="community-source-refs"><span>随作保留的来源</span><p v-for="(r,i) in selected.source_refs" :key="i">{{refText(r)}}</p></div><section v-if="selected.knowledge_refs?.length" class="community-knowledge"><span>随作保留的知识参考</span><article v-for="a in selected.knowledge_refs"><h3>{{a.title}}</h3><p>{{a.source_scope||a.source}}</p><a v-for="r in a.source_refs" :href="r.url" target="_blank" rel="noopener noreferrer">{{r.organization}} · {{r.title}} ↗</a></article></section><p class="community-expression-note">这里的名称与说明属于当代创作者的表达。引用传统图元时，仍需结合其来源与使用语境理解。</p><div class="community-detail-actions"><button class="community-start" @click="emit('create',selected.id)">让这枚纹样入器 →</button><button @click="emit('edit',selected)">沿这份作品继续画</button></div></div></section>
</main>
</template>

